#!/usr/bin/env bash

# ============================================================
# SSH key update guard
# ============================================================
#
# Purpose:
#   Report that SSH keys have no automatic package update.
#
# Notes:
#   Existing keys are never regenerated by the updater.
# ============================================================

set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$SCRIPT_DIR/../.tools/update-runtime.sh"
module_update_entrypoint ssh-key "$@"